// fix-school-app-v24.7.cjs — Private School App (SSSPS Info) v24.7 DELTA fix
// RUN: place this file in the project root (next to package.json) and run:
//   node fix-school-app-v24.7.cjs
// THIS IS THE v24.7-ONLY SCRIPT. It only works on a project where v24.6
// was already applied (package.json says 24.6.0). If you have NOT run v24.6
// yet, run the v24.6 script first (fix-school-app-v24.6.cjs), then this one.
// It backs up every file it changes to <file>.bak first, then applies the
// v24.7 files, then typecheck (npm run lint), tests (npm test) and build
// (npm run build). Safe to run twice: the second run reports everything
// already applied.
// WHAT v24.7 FIXES (the v24.6 audit leftovers, done the best way):
//  - Finance is one source of truth now: recording a fee writes the
//    transaction AND the school's paid flag together (before, the payment
//    form wrote only the transaction and the fee modal wrote only the
//    flag, so the two disagreed; the per-school total also counted a fee
//    twice when it existed in both places).
//  - Voucher numbers can no longer collide when two admins record on the
//    same day (the number is taken from a freshly fetched list). The old
//    fee-data migration is retry-safe now (already-migrated records are
//    skipped, and migrated records get a voucher number).
//  - Audit Logs tab is alive: school add/edit/delete, payments, admin
//    add/remove, school-account creation, announcements and request
//    approvals are now written to the audit log.
//  - Update Requests tab is alive: the School Portal can now ask the
//    admin to change the school name, level or student range, and the
//    admin approves/rejects in the tab. The school sees its own requests'
//    status. Phone/address/township/zone stay directly editable.
//  - Academic year is one setting now: every form uses the Finance
//    "Global Academic Year" (or the current year, June start) instead of
//    hard-coded 2024-2025 / 2025-2026. A new school no longer gets an
//    invented 200,000 kyat fee, and changing the student range no longer
//    overwrites a fee the admin typed.
//  - Dashboard shows real money only: missing fees no longer become a
//    tier default or 200,000; inactive schools are left out of the money
//    totals; the guest card label no longer says "other income" for what
//    is really the annual-fee total; sports/event counts show "—" when
//    the read fails instead of a false 0.
//  - Admin role no longer goes stale after a refresh (the session is
//    re-read on every auth change). Password change no longer reports
//    success when only a reset email was sent, and password fields are
//    hidden while typing.
//  - No more orphaned accounts: a school that already has an account
//    cannot be given a second one, and a failed link deletes the
//    just-created Auth user again (same for a failed admin creation).
//    Deleting an admin now warns that the Auth account must also be
//    removed in Firebase Console.
//  - Optimistic edits roll back: if Firestore rejects a school or
//    announcement edit/delete, the screen and the offline cache go back
//    to the old values instead of looking saved.
//  - Excel school import no longer duplicates on re-upload (name +
//    township), reports which rows failed, and says how many were
//    skipped. Duplicate-school cleanup now matches name + township +
//    zone (not name alone) and survives a single failed delete.
//    Athlete Excel import is chunked (400 per batch) so a 500+ row file
//    no longer fails entirely.
//  - Silent admin buttons (event on/off and delete, sports event delete
//    and status change, athlete delete, request delete) now show an
//    error when they fail.
//  - School Login / School Portal is in the menu now. Receipt no longer
//    crashes on old transactions missing a date/amount, and its back
//    button lands on the Admin Finance tab. Portal athletes are matched
//    by school id (not the free-text name), and a school can delete an
//    activity it posted.
//  - firestore.rules is updated so a school can read its own change
//    requests. Publish it in Firebase Console (Firestore > Rules >
//    Publish) after running this script, or the portal's request status
//    list stays empty.
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { execSync } = require('child_process');

const ROOT = process.cwd();
function log(tag, msg) { console.log('[' + tag + '] ' + msg); }
function sha1(buf) { return crypto.createHash('sha1').update(buf).digest('hex'); }
function run(cmd, label) {
  log('RUN', label + ': ' + cmd);
  try {
    execSync(cmd, { cwd: ROOT, stdio: 'inherit', shell: true });
    log('OK', label + ' passed');
    return true;
  } catch (e) {
    log('FAIL', label + ' failed (see output above)');
    return false;
  }
}

// Sanity check: are we in the school app project root?
if (!fs.existsSync(path.join(ROOT, 'src', 'pages', 'Admin.tsx')) || !fs.existsSync(path.join(ROOT, 'firestore.rules'))) {
  console.error('[ERROR] Project root not found. Run this script from the project folder (the one with package.json, src/pages/Admin.tsx and firestore.rules).');
  process.exit(1);
}

// Guard: this delta only makes sense on top of v24.6.
let pkgVersion = null;
try { pkgVersion = JSON.parse(fs.readFileSync(path.join(ROOT, 'package.json'), 'utf8')).version; } catch (e) {}
if (pkgVersion !== '24.6.0' && pkgVersion !== '24.7.0') {
  console.error('[ERROR] This is the v24.7-ONLY script and your project is at version ' + (pkgVersion || '(unknown)') + ', not v24.6.');
  console.error('        Run the v24.6 script first (fix-school-app-v24.6.cjs), then run this one.');
  process.exit(1);
}
if (pkgVersion === '24.7.0') {
  console.log('[NOTE] package.json already says 24.7.0 — checking whether all v24.7 files are in place...');
}

